-- Generated from reviewed JSON. Apply only after supabase_station_content_v2.sql.
begin;
do $station_release$
declare
  v_release_id uuid;
  v_release_status text;
  v_created_by uuid;
  v_is_admin boolean;
  v_item_count integer;
  v_invalid_day_count integer;
begin
  v_created_by := auth.uid();
  if v_created_by is null then
    select p.id into v_created_by from public.profiles p where p.role = 'admin' order by p.id limit 1;
  end if;
  select exists(select 1 from public.profiles p where p.id = v_created_by and p.role = 'admin') into v_is_admin;
  if v_created_by is null or not coalesce(v_is_admin, false) then
    raise exception 'station_release_import_requires_admin_profile';
  end if;
  insert into public.station_content_releases(version, grade, station_id, title, status, notes, created_by)
  values('g6-st1-2026.1', 6, 'g6_st1', 'Lớp 6 - Trạm 1: Kính hiển vi và tế bào', 'draft', 'Bản thí điểm. Nội dung được đối chiếu theo SGK KHTN 6 Kết nối tri thức; TXT OCR chỉ dùng để tìm kiếm, không dùng làm nguồn xác nhận cuối.', v_created_by)
  on conflict (version) do update set
    title = case when station_content_releases.status = 'draft' then excluded.title else station_content_releases.title end,
    notes = case when station_content_releases.status = 'draft' then excluded.notes else station_content_releases.notes end,
    updated_at = case when station_content_releases.status = 'draft' then now() else station_content_releases.updated_at end
  returning id into v_release_id;
  select status into v_release_status from public.station_content_releases where id = v_release_id for update;
  if v_release_status <> 'draft' then raise exception 'release_version_is_immutable'; end if;
  delete from public.station_content_items where release_id = v_release_id;
  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
  values(v_release_id, 6, 'g6_st1', 1, 1, 'quiz', 'Chọn đáp án chính xác', 'Nhận biết bộ phận chính và thực hiện đúng trình tự sử dụng kính hiển vi quang học.', '{"question":"Khi bắt đầu quan sát, nên chọn vật kính nào?","options":["Vật kính có độ phóng đại nhỏ nhất","Vật kính có độ phóng đại lớn nhất","Vật kính bất kì","Không cần vật kính"],"hint":"Bắt đầu với trường quan sát rộng."}'::jsonb, '{"value":"Vật kính có độ phóng đại nhỏ nhất","explanation":"Vật kính nhỏ giúp tìm mẫu dễ hơn trước khi tăng độ phóng đại."}'::jsonb, '[{"source":"SGK Khoa học tự nhiên 6 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 4. Sử dụng kính hiển vi quang học","pages":"17-18"}]'::jsonb);
  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
  values(v_release_id, 6, 'g6_st1', 1, 2, 'match', 'Nối cấu trúc với đặc điểm', 'Nhận biết bộ phận chính và thực hiện đúng trình tự sử dụng kính hiển vi quang học.', '{"leftItems":["Thị kính","Vật kính","Ốc điều chỉnh"],"rightItems":["Điều chỉnh khoảng cách để ảnh rõ","Phóng đại ảnh của vật","Nơi đặt mắt để quan sát"],"hint":"Phân biệt vai trò của “Thị kính” và “Vật kính” trước khi nối. Mô tả của “Thị kính” bắt đầu bằng “N”."}'::jsonb, '{"value":[{"left":"Thị kính","right":"Nơi đặt mắt để quan sát"},{"left":"Vật kính","right":"Phóng đại ảnh của vật"},{"left":"Ốc điều chỉnh","right":"Điều chỉnh khoảng cách để ảnh rõ"}],"explanation":"Thị kính: Nơi đặt mắt để quan sát; Vật kính: Phóng đại ảnh của vật; Ốc điều chỉnh: Điều chỉnh khoảng cách để ảnh rõ."}'::jsonb, '[{"source":"SGK Khoa học tự nhiên 6 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 4. Sử dụng kính hiển vi quang học","pages":"17-18"}]'::jsonb);
  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
  values(v_release_id, 6, 'g6_st1', 1, 3, 'fill', 'Hoàn thiện kiến thức', 'Nhận biết bộ phận chính và thực hiện đúng trình tự sử dụng kính hiển vi quang học.', '{"sentence":"Kính hiển vi quang học giúp quan sát những vật có kích thước [blank] mà mắt thường khó thấy.","hint":"Xét ngữ cảnh của ô trống trong “Kính hiển vi quang học giúp quan sát những vật có kích thước [blank] mà mắt thường khó thấy.”. Từ cần chọn bắt đầu bằng “n” và gồm 2 tiếng."}'::jsonb, '{"value":"nhỏ bé","explanation":"Từ cần điền là “nhỏ bé”."}'::jsonb, '[{"source":"SGK Khoa học tự nhiên 6 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 4. Sử dụng kính hiển vi quang học","pages":"17-18"}]'::jsonb);
  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
  values(v_release_id, 6, 'g6_st1', 1, 4, 'category', 'Phân loại đúng nhóm', 'Nhận biết bộ phận chính và thực hiện đúng trình tự sử dụng kính hiển vi quang học.', '{"categories":["Bộ phận quang học","Bộ phận cơ học"],"items":["Thị kính","Vật kính","Bàn kính","Ốc điều chỉnh"],"hint":"Phân biệt hai nhóm “Bộ phận quang học” và “Bộ phận cơ học” theo đặc điểm của từng mục. “Thị kính” thuộc nhóm “Bộ phận quang học”."}'::jsonb, '{"value":[{"name":"Thị kính","catIndex":0},{"name":"Vật kính","catIndex":0},{"name":"Bàn kính","catIndex":1},{"name":"Ốc điều chỉnh","catIndex":1}],"explanation":"Thị kính thuộc nhóm Bộ phận quang học; Vật kính thuộc nhóm Bộ phận quang học; Bàn kính thuộc nhóm Bộ phận cơ học; Ốc điều chỉnh thuộc nhóm Bộ phận cơ học."}'::jsonb, '[{"source":"SGK Khoa học tự nhiên 6 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 4. Sử dụng kính hiển vi quang học","pages":"17-18"}]'::jsonb);
  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
  values(v_release_id, 6, 'g6_st1', 1, 5, 'dragdrop', 'Kéo từ hoàn thành câu', 'Nhận biết bộ phận chính và thực hiện đúng trình tự sử dụng kính hiển vi quang học.', '{"textWithBlanks":"Sau khi đặt tiêu bản, cần điều chỉnh [blank] để ảnh quan sát rõ nét.","bankWords":["ốc điều chỉnh","chân kính","kẹp tiêu bản"],"hint":"Thử từng từ trong kho vào câu “Sau khi đặt tiêu bản, cần điều chỉnh [blank] để ảnh quan sát rõ nét.” để tạo phát biểu đúng. Từ cần chọn bắt đầu bằng “ố” và gồm 3 tiếng."}'::jsonb, '{"value":"ốc điều chỉnh","explanation":"Từ đúng là “ốc điều chỉnh”."}'::jsonb, '[{"source":"SGK Khoa học tự nhiên 6 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 4. Sử dụng kính hiển vi quang học","pages":"17-18"}]'::jsonb);
  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
  values(v_release_id, 6, 'g6_st1', 2, 1, 'quiz', 'Chọn đáp án chính xác', 'Nêu được khái niệm tế bào và nhận biết sự đa dạng về hình dạng, kích thước của tế bào.', '{"question":"Đơn vị cấu trúc và chức năng cơ bản của cơ thể sống là gì?","options":["Tế bào","Mô","Cơ quan","Hệ cơ quan"],"hint":"Đây là đơn vị nhỏ nhất có thể thực hiện các hoạt động sống."}'::jsonb, '{"value":"Tế bào","explanation":"Tế bào là đơn vị cấu trúc và chức năng cơ bản của cơ thể sống."}'::jsonb, '[{"source":"SGK Khoa học tự nhiên 6 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 1. Tế bào - Đơn vị cơ bản của sự sống","pages":"76-78"}]'::jsonb);
  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
  values(v_release_id, 6, 'g6_st1', 2, 2, 'match', 'Nối cấu trúc với đặc điểm', 'Nêu được khái niệm tế bào và nhận biết sự đa dạng về hình dạng, kích thước của tế bào.', '{"leftItems":["Tế bào da người","Tế bào thần kinh","Tế bào thịt lá"],"rightItems":["Có dạng gần hình hộp","Có phần kéo dài","Dẹt và xếp sát nhau"],"hint":"Phân biệt vai trò của “Tế bào da người” và “Tế bào thần kinh” trước khi nối. Mô tả của “Tế bào da người” bắt đầu bằng “D”."}'::jsonb, '{"value":[{"left":"Tế bào da người","right":"Dẹt và xếp sát nhau"},{"left":"Tế bào thần kinh","right":"Có phần kéo dài"},{"left":"Tế bào thịt lá","right":"Có dạng gần hình hộp"}],"explanation":"Tế bào da người: Dẹt và xếp sát nhau; Tế bào thần kinh: Có phần kéo dài; Tế bào thịt lá: Có dạng gần hình hộp."}'::jsonb, '[{"source":"SGK Khoa học tự nhiên 6 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 1. Tế bào - Đơn vị cơ bản của sự sống","pages":"76-78"}]'::jsonb);
