  values(v_release_id, 6, 'g6_st1', 2, 3, 'fill', 'Hoàn thiện kiến thức', 'Nêu được khái niệm tế bào và nhận biết sự đa dạng về hình dạng, kích thước của tế bào.', '{"sentence":"Các tế bào khác nhau có hình dạng và kích thước [blank].","hint":"Xét ngữ cảnh của ô trống trong “Các tế bào khác nhau có hình dạng và kích thước [blank].”. Từ cần chọn bắt đầu bằng “k” và gồm 2 tiếng."}'::jsonb, '{"value":"khác nhau","explanation":"Từ cần điền là “khác nhau”."}'::jsonb, '[{"source":"SGK Khoa học tự nhiên 6 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 1. Tế bào - Đơn vị cơ bản của sự sống","pages":"76-78"}]'::jsonb);
