  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
  values(v_release_id, 6, 'g6_st1', 10, 5, 'dragdrop', 'Kéo từ hoàn thành câu', 'Hệ thống hoá kiến thức về kính hiển vi, cấu tạo, sự lớn lên và phân chia của tế bào.', '{"textWithBlanks":"Sự lớn lên và [blank] của tế bào giúp cơ thể sinh trưởng.","bankWords":["phân chia","bay hơi","hoà tan"],"hint":"Thử từng từ trong kho vào câu “Sự lớn lên và [blank] của tế bào giúp cơ thể sinh trưởng.” để tạo phát biểu đúng. Từ cần chọn bắt đầu bằng “p” và gồm 2 tiếng."}'::jsonb, '{"value":"phân chia","explanation":"Từ đúng là “phân chia”."}'::jsonb, '[{"source":"SGK Khoa học tự nhiên 6 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 1-4. Tế bào","pages":"76-87"}]'::jsonb);
  select count(*) into v_item_count from public.station_content_items where release_id = v_release_id;
  if v_item_count <> 50 then
    raise exception 'station_release_import_requires_50_items';
  end if;
  select count(*) into v_invalid_day_count from (
    select day_index
    from public.station_content_items
    where release_id = v_release_id
    group by day_index
    having count(*) <> 5 or count(distinct game_type) <> 5
  ) invalid_days;
  if v_invalid_day_count <> 0 then
    raise exception 'station_release_import_requires_five_unique_games_per_day';
  end if;
end;
$station_release$;
